floor_fn:
"""
    function used to remove/replace top-level matching parenthesis from a string

    :param inv: input string

    :param replace_with: string to replace matching parenthesis with

    :return: input string without first set of matching parentheses
    """
def remove_parentheses(inv: Any, replace_with: Any = '') -> object {
    k = 0;
    lp = '';
    out = '';
    for c in inv {
        if (c == '(') {
            k += 1;
            lp = c;
        } elif (c == ')') {
            k -= 1;
            lp += c;
            if (k == 0) {
                out += replace_with;
            }
        } elif (k == 0) {
            out += c;
        }
    }
    return out;
}

test_blocks:
test "t0" {
    assert (
        remove_parentheses('this is a string without parentheses')
        == 'this is a string without parentheses'
    );;
}

test "t1" {
    assert (remove_parentheses('()') == '');;
}

test "t2" {
    assert (remove_parentheses('((a)b(c)d(e)f)g') == 'g');;
}

test "t3" {
    assert (remove_parentheses('a(b(c(d)e)f)') == 'a');;
}

test "t4" {
    assert (remove_parentheses('a(b(c)d(e)(f)g)h') == 'ah');;
}

test "t5" {
    assert (remove_parentheses('a(b(c)d(e)f)g') == 'ag');;
}

test "t6" {
    assert (remove_parentheses('a(b(c)(d)e)f') == 'af');;
}

test "t7" {
    assert (remove_parentheses(r'hi()') == 'hi');;
}

test "t8" {
    assert (remove_parentheses(remove_parentheses('abcd')) == 'abcd');;
}

test "t9" {
    assert (remove_parentheses('a(b(c(d)e)f)g') == 'ag');;
}

test "t10" {
    assert (remove_parentheses('a((b(c)d)e)f') == 'af');;
}

test "t11" {
    assert (remove_parentheses('hello world') == 'hello world');;
}
